<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$id=(int)($_GET['id']??0);if(!$pdo||$id<1){header('Location: products.php');exit;}$s=$pdo->prepare('SELECT product_name FROM products WHERE id=?');$s->execute([$id]);$p=$s->fetch();if(!$p){header('Location: products.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();log_admin_activity('product_deleted','Product ID: '.$id);$pdo->prepare('DELETE FROM products WHERE id=?')->execute([$id]);header('Location: products.php');exit;}?><!doctype html><html lang="en"><head><meta charset="utf-8"><title>Delete Product</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><section class="card"><h1>Delete product?</h1><p><?=e($p['product_name'])?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><button>Delete permanently</button> <a href="products.php">Cancel</a></form></section></main></body></html>
